<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class Order extends Model {protected $primaryKey='order_id';public $timestamps=false;protected $fillable=['user_id','coupon_id','order_number','subtotal','discount_amount','shipping_cost','tax_amount','total_amount','status','order_date'];protected $casts=['order_date'=>'datetime'];public function user(){return $this->belongsTo(User::class,'user_id','user_id');}public function coupon(){return $this->belongsTo(Coupon::class,'coupon_id','coupon_id');}public function items(){return $this->hasMany(OrderItem::class,'order_id','order_id');}public function payment(){return $this->hasOne(Payment::class,'order_id','order_id');}public function shipment(){return $this->hasOne(Shipment::class,'order_id','order_id');}}
